{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket is not configured to block public ACLs, potentially allowing public access to sensitive CloudTrail logs."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks a Public Access block, which could expose CloudTrail logs to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket storing CloudTrail logs does not have access logging enabled, making it difficult to track and monitor access to these sensitive logs."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n\n  target_bucket = aws_s3_bucket.cloudtrail_logs.id\n  target_prefix = \"logs/\"\n}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to block public access and aws_s3_bucket_logging to enable access logging for the S3 bucket storing CloudTrail logs."
}
